executions.stdout:
# Biodiversitätsflächen auf Ackerflächen (Kap. 6.1, 8.1-8.4, 10; SRL 2.1 B Anlage von
# Biodiversitätsflächen auf Ackerflächen lit. a-g).
package oepul.o6_1b

arable_div_cfg := general.arable_div

is_arable_div(p) if {
	p.land_use == "arable"
	not land_use_type(p) in {"LSE Mehrnutzenhecke", "GLÖZ-Landschaftselement", "Agroforststreifen"}
	count(codes(p) & {"DIV", "DIVRS"}) > 0
}

div_from_other_measure(p) if count(codes(p) & {c | some c in lists.arable_div_other_measure_codes}) > 0

div_gloez4(p) if object.get(div_info(p), "gloez4_buffer_strip", false) == true

div_gloez8(p) if object.get(div_info(p), "gloez8_fallow", false) == true

# "reine" DIV-Fläche ohne zusätzlichen Maßnahmencode und ohne GLÖZ 4-Pufferstreifen (Kap. 8.1)
div_pure(p) if {
	is_arable_div(p)
	not div_from_other_measure(p)
	not div_gloez4(p)
}

nat_auflagen(p) := {a | some a in object.get(div_info(p), "nat_auflagen", [])}

# Anrechenbarkeit für die 7 %-Mindestanlage (Kap. 6.1.3)
arable_div_creditable(p) if {
	is_arable_div(p)
	not has_code(p, "K20")
	not div_from_other_measure(p)
	not div_gloez8(p)
}

arable_div_creditable(p) if {
	is_arable_div(p)
	not has_code(p, "K20")
	not div_from_other_measure(p)
	div_gloez8(p)
	year <= 2024
}

arable_div_creditable(p) if {
	is_arable_div(p)
	has_code(p, "NAT")
	lists.parameters.arable_div_nat_required_auflage in nat_auflagen(p)
	object.get(div_info(p), "nat_area_used", false) == false
}

arable_div_creditable(p) if {
	is_arable_div(p)
	has_code(p, "EBW")
	object.get(div_info(p), "ebw_fallow", true) == true
}

arable_div_creditable(p) if {
	is_arable_div(p)
	count(codes(p) & {"BAW", "AG"}) > 0
	object.get(div_info(p), "care_rules_6_1_4_2_met", true) == true
}

hedges := object.get(input, ["land", "multi_use_hedges"], [])

hedge_div_creditable(h) if {
	object.get(h, "div_coded", false) == true
	object.get(h, "herbaceous_care_rules_met", false) == true
}

arable_div_credit_ha := sum([area(p) | some p in parcels; arable_div_creditable(p)]) + sum([object.get(h, "area_ha", 0) | some h in hedges; hedge_div_creditable(h)])

arable_div_total_ha := sum([area(p) | some p in parcels; is_arable_div(p)])

arable_div_pure_ha := sum([area(p) | some p in parcels; div_pure(p)])

arable_div_obligation_applies if arable_area_ha > arable_div_cfg.threshold_ha_exclusive

arable_div_required_ha := arable_div_cfg.min_share * arable_area_ha if arable_div_obligation_applies

arable_div_required_ha := 0 if not arable_div_obligation_applies

# Erfüllung direkt auf Acker
arable_div_minimum_met if arable_div_credit_ha >= arable_div_required_ha

# Betriebe unter 10 ha Acker: Erfüllung auch über zusätzliche Grünland-Biodiversitätsflächen (Kap. 6.1.1)
arable_div_minimum_met if {
	arable_area_ha < arable_div_cfg.grassland_substitution_below_ha
	grassland_div_credit_ha >= grassland_div_required_ha
	arable_div_credit_ha + grassland_div_credit_ha >= arable_div_required_ha + grassland_div_required_ha
}

violations contains {"rule_id": "O61B-DA-001", "message": sprintf("Acker-Biodiversitätsflächen %v ha unter erforderlichen 7 %% (%v ha)", [round2(arable_div_credit_ha), round2(arable_div_required_ha)])} if {
	arable_div_obligation_applies
	not arable_div_minimum_met
}

# --- Feldstücksbezogene Anlageverpflichtung (Kap. 6.1.2) ---------------------------------

field_piece_div_ha(fp_id) := sum([area(p) | some p in parcels; object.get(p, "field_piece_id", "") == fp_id; field_piece_div_counts(p)])

field_piece_div_counts(p) if arable_div_creditable(p)

field_piece_div_counts(p) if {
	is_arable_div(p)
	not arable_div_creditable(p)
	div_from_other_measure(p)
}

field_piece_extra_ha(fp) := object.get(fp, "gloez_lse_area_ha", 0) + object.get(fp, "agroforest_strip_area_ha", 0) if year >= 2025

field_piece_extra_ha(fp) := object.get(fp, "gloez_lse_area_ha", 0) if year < 2025

violations contains {"rule_id": "O61B-DA-004", "message": sprintf("Acker-Feldstück %s (> 5 ha) mit weniger als 0,15 ha Biodiversitätsflächen", [fp.field_piece_id])} if {
	arable_area_ha >= arable_div_cfg.field_piece_rule_min_farm_arable_ha
	some fp in field_pieces
	fp.land_use == "arable"
	fp.area_ha > arable_div_cfg.field_piece_threshold_ha_exclusive
	field_piece_div_ha(fp.field_piece_id) + field_piece_extra_ha(fp) < arable_div_cfg.field_piece_min_ha
}

# --- Ansaat (Kap. 6.1.4.1) -----------------------------------------------------------------

# Flächen, für die alle Bewirtschaftungsauflagen gem. 6.1.4 gelten
div_full_rules_apply(p) if {
	is_arable_div(p)
	not div_from_other_measure(p)
}

seed_mixture(p) := object.get(div_info(p), "seed_mixture", {})

first_declared_year(p) := object.get(div_info(p), "first_declared_year", year)

sowing_exempt(p) if object.get(div_info(p), "sowing_exempt_existing", false) == true

is_new_sowing(p) if object.get(div_info(p), "is_new_sowing", false) == true

violations contains {"rule_id": "O61B-DA-010", "message": sprintf("Acker-Biodiversitätsfläche %s: Neuansaat einer Bienenmischung erforderlich", [p.parcel_id])} if {
	some p in parcels
	div_full_rules_apply(p)
	first_declared_year(p) == year
	not sowing_exempt(p)
	not is_new_sowing(p)
}

violations contains {"rule_id": "O61B-DA-010", "message": sprintf("Acker-Biodiversitätsfläche %s: Saatgutmischung erfüllt nicht 7 insektenblütige Partner aus 3 Familien mit max. 10 %% nicht insektenblütigen Partnern", [p.parcel_id])} if {
	some p in parcels
	div_full_rules_apply(p)
	is_new_sowing(p)
	not bee_mixture_ok(seed_mixture(p))
}

bee_mixture_ok(m) if {
	object.get(m, "insect_pollinated_partners", 0) >= arable_div_cfg.min_insect_partners
	object.get(m, "plant_families", 0) >= arable_div_cfg.min_families
	object.get(m, "non_insect_share_percent", 100) <= arable_div_cfg.max_non_insect_share_percent
}

violations contains {"rule_id": "O61B-DA-012", "message": sprintf("Acker-Biodiversitätsfläche %s: Neuansaat nach dem 15. Mai", [p.parcel_id])} if {
	some p in parcels
	div_full_rules_apply(p)
	is_new_sowing(p)
	sd := object.get(div_info(p), "sowing_date", null)
	sd != null
	date_year(sd) == year
	md(sd) > arable_div_cfg.sowing_deadline
}

# --- Umbruch / Zweijährigkeit (Kap. 6.1.4.1, 6.1.5) ------------------------------------------

earliest_break_date(p) := sprintf("%d-07-31", [first_declared_year(p) + 1]) if {
	object.get(div_info(p), "followed_by_winter_crop_or_catch_crop", false) == true
}

earliest_break_date(p) := sprintf("%d-09-15", [first_declared_year(p) + 1]) if {
	object.get(div_info(p), "followed_by_winter_crop_or_catch_crop", false) != true
}

break_before_allowed(p, bd) if {
	object.get(div_info(p), "followed_by_winter_crop_or_catch_crop", false) == true
	bd <= earliest_break_date(p)
}

break_before_allowed(p, bd) if {
	object.get(div_info(p), "followed_by_winter_crop_or_catch_crop", false) != true
	bd < earliest_break_date(p)
}

two_year_exception(p) if object.get(div_info(p), "loss_of_control", false) == true

two_year_exception(p) if object.get(div_info(p), "converted_to_grassland", false) == true

violations contains {"rule_id": "O61B-DA-012", "message": sprintf("Acker-Biodiversitätsfläche %s vor Ablauf der Zweijährigkeit umgebrochen", [p.parcel_id])} if {
	some p in parcels
	is_arable_div(p)
	bd := object.get(div_info(p), "break_date", null)
	bd != null
	break_before_allowed(p, bd)
	not two_year_exception(p)
}

violations contains {"rule_id": "O61B-DA-012", "message": sprintf("Umgebrochene Grünbrache-Biodiversitätsfläche %s vor 31.12. genutzt", [p.parcel_id])} if {
	some p in parcels
	is_arable_div(p)
	land_use_type(p) == "Grünbrache"
	bd := object.get(div_info(p), "break_date", null)
	bd != null
	some e in use_events(p)
	e.date > bd
	date_year(e.date) == date_year(bd)
	e.type in {"mow", "graze", "harvest"}
}

# --- Pflege-/Nutzungsauflagen (Kap. 6.1.4.2) -------------------------------------------------

# Reinigungsschnitt im Jahr der ersten Beantragung auf Neuansaatflächen (ab 2025) ohne Verbringung
# zählt weder zur Maximalanzahl noch zur 25 %-Grenze.
is_uncounted_cleaning_cut(p, e) if {
	object.get(e, "cleaning_cut", false) == true
	object.get(e, "removed", false) == false
	first_declared_year(p) == year
	is_new_sowing(p)
	year >= 2025
}

# Häckseln / Pflegemahd ohne Verbringung unmittelbar nach dem Weidegang zählt nicht (ab 2025)
is_uncounted_after_grazing(e) if {
	year >= 2025
	object.get(e, "after_grazing_care", false) == true
	object.get(e, "removed", false) == false
}

counted_use(p, e) if {
	e.type in {"mow", "chop", "graze"}
	not is_uncounted_cleaning_cut(p, e)
	not is_uncounted_after_grazing(e)
}

counted_uses(p) := [e | some e in use_events(p); counted_use(p, e); date_year(e.date) == year]

invasive_exception(p) if {
	object.get(o6_1b_input, "invasive_species_over_25_percent_of_arable_div", false) == true
	object.get(div_info(p), "invasive_species_present", false) == true
}

# Flächen mit vorrangiger Projektbestätigung (NAT/EBW)
div_project_precedence(p) if count(codes(p) & {"NAT", "EBW"}) > 0

early_used(p) if {
	some e in counted_uses(p)
	md(e.date) < arable_div_cfg.late_use_date
}

early_use_area(pred) := sum([area(p) | some p in parcels; is_arable_div(p); early_used(p); early_use_class(p) == pred])

early_use_class(p) := "project" if div_project_precedence(p)

early_use_class(p) := "invasive" if {
	not div_project_precedence(p)
	invasive_exception(p)
}

early_use_class(p) := "opted_out" if {
	not div_project_precedence(p)
	not invasive_exception(p)
	opted_out(p)
}

early_use_class(p) := "regular" if {
	not div_project_precedence(p)
	not invasive_exception(p)
	not opted_out(p)
}

arable_div_early_share := share(early_use_area("regular") + early_use_area("project"), arable_div_total_ha)

violations contains {"rule_id": "O61B-DA-018", "message": sprintf("Mehr als 25 %% der Acker-Biodiversitätsflächen vor dem 1. August genutzt (%v %%)", [round2(arable_div_early_share * 100)])} if {
	early_use_area("regular") > 0
	arable_div_early_share > 1 - arable_div_cfg.late_use_share
}

violations contains {"rule_id": "O61B-DA-019", "message": sprintf("Acker-Biodiversitätsfläche %s: Beweidung vor dem 1. August bzw. (bis 2024) Beweidung unzulässig", [p.parcel_id])} if {
	some p in parcels
	div_full_rules_apply(p)
	not opted_out(p)
	some e in use_events(p)
	e.type == "graze"
	date_year(e.date) == year
	grazing_not_allowed(e)
}

grazing_not_allowed(_) if year <= 2024

grazing_not_allowed(e) if {
	year >= 2025
	md(e.date) < arable_div_cfg.late_use_date
}

violations contains {"rule_id": "O61B-DA-019", "message": sprintf("Acker-Biodiversitätsfläche %s: Drusch nicht erlaubt", [p.parcel_id])} if {
	some p in parcels
	is_arable_div(p)
	some e in use_events(p)
	e.type == "thresh"
}

violations contains {"rule_id": "O61B-DA-019", "message": sprintf("Acker-Biodiversitätsfläche %s: mehr als 2 Nutzungen im Jahr", [p.parcel_id])} if {
	some p in parcels
	is_arable_div(p)
	not div_project_precedence(p)
	count(counted_uses(p)) > arable_div_cfg.max_uses_per_year
	not invasive_exception(p)
	not third_use_2026_allowed(p)
}

violations contains {"rule_id": "O61B-DA-020", "message": sprintf("Acker-Biodiversitätsfläche %s: nach Mahd vor dem 1. August max. 1 Beweidung", [p.parcel_id])} if {
	some p in parcels
	div_full_rules_apply(p)
	year >= 2025
	some m in counted_uses(p)
	m.type in {"mow", "chop"}
	md(m.date) < arable_div_cfg.late_use_date
	count([g | some g in counted_uses(p); g.type == "graze"]) > 1
}

violations contains {"rule_id": "O61B-DA-018", "message": sprintf("Acker-Biodiversitätsfläche %s: keine Mahd/Häckseln/Weide innerhalb von zwei Jahren", [p.parcel_id])} if {
	some p in parcels
	div_full_rules_apply(p)
	first_declared_year(p) < year
	object.get(div_info(p), "used_previous_year", false) == false
	count(counted_uses(p)) == 0
	object.get(div_info(p), "year_complete", false) == true
}

violations contains {"rule_id": "O61B-DA-023", "message": sprintf("Acker-Biodiversitätsfläche %s: Reinigungsschnitt nur im Jahr der ersten Beantragung auf Neuansaatflächen zulässig", [p.parcel_id])} if {
	some p in parcels
	is_arable_div(p)
	some e in use_events(p)
	object.get(e, "cleaning_cut", false) == true
	md(e.date) < arable_div_cfg.late_use_date
	not cleaning_cut_allowed(p)
}

cleaning_cut_allowed(p) if {
	first_declared_year(p) == year
	is_new_sowing(p)
	year >= 2025
}

# --- Betriebsmitteleinsatz und Befahren (Kap. 6.1.4.3, 6.1.4.4) -------------------------------

violations contains {"rule_id": "O61B-DA-025", "message": sprintf("Düngung auf Acker-Biodiversitätsfläche %s", [p.parcel_id])} if {
	some p in parcels
	div_full_rules_apply(p)
	some f in fertilizer_applications(p)
	f.date >= sprintf("%d-01-01", [first_declared_year(p)])
}

violations contains {"rule_id": "O61B-DA-026", "message": sprintf("Beseitigung der Biodiversitätsfläche %s nicht mit mechanischen Methoden", [p.parcel_id])} if {
	some p in parcels
	is_arable_div(p)
	method := object.get(div_info(p), "removal_implement", null)
	method != null
	not method in lists.div_mechanical_removal_implements
}

violations contains {"rule_id": "O61B-DA-027", "message": sprintf("Acker-Biodiversitätsfläche %s: unzulässige Nutzung (%s)", [p.parcel_id, u])} if {
	some p in parcels
	is_arable_div(p)
	some u in object.get(p, ["operations", "prohibited_uses"], [])
	u in {"irrigation_installation", "driving", "machine_parking", "trailer_parking", "storage", "turning_area"}
}

# --- Zuschlag Neuansaat mit regionaler Acker-Saatgutmischung DIVRS (Kap. 6.1.5) -------------

is_arable_divrs(p) if {
	is_arable_div(p)
	has_code(p, "DIVRS")
}

regional_mixture_ok(m) if {
	object.get(m, "species_count", 0) >= data.o6_1b.regional_seed_species.requirements.min_species
	object.get(m, "family_count", 0) >= data.o6_1b.regional_seed_species.requirements.min_families
	object.get(m, "seed_rate_kg_ha", 0) >= data.o6_1b.regional_seed_species.requirements.min_seed_rate_kg_ha
	object.get(m, "regional_origin_certified", false) == true
	object.get(m, "documented", false) == true
	species_list_ok(m)
}

# Ohne Ökotypensaatgut: nur Arten aus Kapitel 14 und max. 5 Gewichtsprozent je Art
species_list_ok(m) if object.get(m, "ecotype_seed_used", false) == true

species_list_ok(m) if {
	object.get(m, "ecotype_seed_used", false) == false
	object.get(m, "max_single_species_weight_percent", 100) <= data.o6_1b.regional_seed_species.requirements.max_single_species_weight_percent
	object.get(m, "species_outside_list", 0) == 0
}

divrs_seed_ok(p) if {
	not object.get(div_info(p), "divrs_interrupted", false) == true
	regional_mixture_ok(seed_mixture(p))
}

divrs_seed_ok(p) if {
	object.get(div_info(p), "divrs_interrupted", false) == true
	is_new_sowing(p)
	regional_mixture_ok(seed_mixture(p))
}

divrs_arable_variant(p) := object.get(div_info(p), "divrs_variant", "sonstiges_feldfutter")

mowings_with_removal(p) := [e | some e in counted_uses(p); e.type == "mow"; object.get(e, "removed", false) == true]

chops(p) := [e | some e in use_events(p); e.type == "chop"; date_year(e.date) == year]

divrs_arable_care_ok(p) if {
	year <= 2024
	count(mowings_with_removal(p)) >= 1
	count(mowings_with_removal(p)) <= 2
	count(chops(p)) == 0
}

divrs_arable_care_ok(p) if {
	year >= 2025
	divrs_arable_variant(p) == "sonstiges_feldfutter"
	count(mowings_with_removal(p)) >= general.divrs_arable.variant_sonstiges_feldfutter.min_mowings
	count(mowings_with_removal(p)) <= general.divrs_arable.variant_sonstiges_feldfutter.max_mowings
	count([e | some e in counted_uses(p); e.type in {"chop", "graze"}]) == 0
}

divrs_arable_care_ok(p) if {
	year >= 2025
	divrs_arable_variant(p) == "gruenbrache"
	count(chops(p)) <= general.divrs_arable.variant_gruenbrache.max_chop_per_year
	every e in chops(p) {
		gruenbrache_chop_date_ok(p, e)
	}
	count([e | some e in use_events(p); e.type in {"mow", "graze"}; date_year(e.date) == year]) == 0
}

gruenbrache_chop_date_ok(_, e) if md(e.date) >= general.divrs_arable.variant_gruenbrache.chop_earliest

gruenbrache_chop_date_ok(p, e) if {
	object.get(e, "cleaning_cut", false) == true
	object.get(e, "removed", false) == false
	first_declared_year(p) == year
}

# Pflegeprüfung erst nach Ablauf des Jahres bzw. wenn Nutzungsdaten vollständig sind
divrs_arable_care_checkable(p) if object.get(div_info(p), "year_complete", false) == true

violations contains {"rule_id": "O61B-DA-028", "message": sprintf("DIVRS-Fläche %s: Anforderungen an die regionale Acker-Saatgutmischung nicht erfüllt", [p.parcel_id])} if {
	some p in parcels
	is_arable_divrs(p)
	not divrs_seed_ok(p)
}

violations contains {"rule_id": "O61B-DA-030", "message": sprintf("DIVRS-Fläche %s: Pflege-/Nutzungsauflagen der gewählten Variante nicht eingehalten", [p.parcel_id])} if {
	some p in parcels
	is_arable_divrs(p)
	divrs_arable_care_checkable(p)
	not divrs_arable_care_ok(p)
}

violations contains {"rule_id": "O61B-DA-029", "message": "DIVRS-Beantragung ohne neuerliche Ansaat nur bis längstens 2028"} if {
	some p in parcels
	is_arable_divrs(p)
	year > general.divrs_arable.last_year_without_resowing
}

# --- Beantragung (Kap. 10) ---------------------------------------------------------------------

arable_div_land_use_allowed(p) if {
	has_code(p, "DIVRS")
	some r in lists.arable_divrs_land_use_types
	r.land_use == land_use_type(p)
	r.from_year <= year
}

arable_div_land_use_allowed(p) if {
	not has_code(p, "DIVRS")
	some r in lists.arable_div_land_use_types
	r.land_use == land_use_type(p)
	r.from_year <= year
}

violations contains {"rule_id": "O61B-AN-003", "message": sprintf("Acker-Biodiversitätsfläche %s mit unzulässiger Schlagnutzungsart %s", [p.parcel_id, land_use_type(p)])} if {
	some p in parcels
	is_arable_div(p)
	not arable_div_land_use_allowed(p)
}

violations contains {"rule_id": "O61B-AN-004", "message": sprintf("Aus Naturschutz/EBW angerechnete Biodiversitätsfläche %s muss als Grünbrache beantragt werden", [p.parcel_id])} if {
	some p in parcels
	is_arable_div(p)
	count(codes(p) & {"NAT", "EBW"}) > 0
	land_use_type(p) != "Grünbrache"
}

violations contains {"rule_id": "O61B-DA-005", "message": sprintf("K20-Ackerfläche %s ist nicht als Biodiversitätsfläche anrechenbar", [p.parcel_id])} if {
	some p in parcels
	is_arable_div(p)
	has_code(p, "K20")
}

# Allgemeine Rahmenbedingungen mehrjähriger Maßnahmen: Flächenabgang, Flächenzugang,
# Maßnahmenübernahme, Ausstieg, Kürzungsstufen und Auszahlung (ATB 5.8, 6, 7, 8, 9; SRL 1.7, 1.9, 1.10, 1.12).
package oepul.o6_1b

area_changes := object.get(input, ["oepul", "area_changes"], {})

# --- Flächenabgang (ATB 7.1; SRL 1.7.2.3) ------------------------------------------------------

previous_measure_area_ha := object.get(area_changes, "previous_year_measure_area_ha", 0)

# Unschädliche Abgänge: Verlust der Verfügungsgewalt und zulässige Nutzungsumwandlungen
exempt_reduction_ha := object.get(area_changes, "loss_of_control_ha", 0) + object.get(area_changes, "permitted_conversion_ha", 0)

relevant_reduction_ha := clamp0((previous_measure_area_ha - object.get(area_changes, "current_measure_area_ha", previous_measure_area_ha)) - exempt_reduction_ha)

area_loss_tolerance_ha := max2(min2(general.area_loss_tolerance.max_share * previous_measure_area_ha, general.area_loss_tolerance.max_ha), general.area_loss_tolerance.always_allowed_ha)

area_reduction_repayment_ha := relevant_reduction_ha if relevant_reduction_ha > area_loss_tolerance_ha

area_reduction_repayment_ha := 0 if relevant_reduction_ha <= area_loss_tolerance_ha

violations contains {"rule_id": "O61B-ATB-009", "message": sprintf("Flächenreduktion %v ha über der Toleranz %v ha: Rückzahlung für die gesamte Differenzfläche", [round2(relevant_reduction_ha), round2(area_loss_tolerance_ha)])} if {
	area_reduction_repayment_ha > 0
}

# --- Flächenzugang (ATB 7.2; SRL 1.7.2.4) -----------------------------------------------------

measure_area_2025_ha := object.get(area_changes, "measure_area_2025_ha", null)

premium_eligible_measure_area_max_ha := max2(measure_area_2025_ha * (1 + general.area_increase.max_increase_share), measure_area_2025_ha + general.area_increase.always_allowed_ha) if {
	year > general.area_increase.base_year
	measure_area_2025_ha != null
}

area_increase_not_eligible_ha := clamp0(object.get(area_changes, "current_measure_area_ha", 0) - premium_eligible_measure_area_max_ha)

# --- Maßnahmenübernahme (ATB 6.3; SRL 1.7.3.1) ---------------------------------------------

takeover := object.get(o6_1b_input, "takeover", null)

takeover_deadline(y) := sprintf("%d-%s", [y, general.takeover_deadline.years_2023_2028]) if y in {2023, 2028}

takeover_deadline(y) := sprintf("%d-%s", [y, general.takeover_deadline.default]) if not y in {2023, 2028}

violations contains {"rule_id": "O61B-ATB-013", "message": "Maßnahmenübernahme nach der Frist (15.04. bzw. 17.04. in 2023/2028)"} if {
	takeover != null
	takeover.date > takeover_deadline(date_year(takeover.date))
}

violations contains {"rule_id": "O61B-ATB-013", "message": "Maßnahmenübernahme führt zu einer Ausweitung auf andere Flächen um mehr als 50 %"} if {
	takeover != null
	object.get(takeover, "extension_share", 0) > general.tolerances.takeover_max_extension_share
}

# --- Ausstieg / Vertragszeitraum (ATB 6, 7.1; SRL 1.7.2, 1.10.5.3) ----------------------------

exit_info := object.get(o6_1b_input, "exit", null)

repayment_of_all_premiums_required if {
	exit_info != null
	exit_info.date < general.deadlines.contract_end
	object.get(exit_info, "reason", "") != "loss_of_control"
	object.get(exit_info, "reason", "") != "revision_clause"
	object.get(exit_info, "reason", "") != "permanent_circumstances_accepted"
	object.get(exit_info, "reason", "") != "measure_switch"
}

# Abmeldung im laufenden Jahr: Maßnahme im betroffenen Förderjahr nicht mehr gültig
no_premium_current_year_due_to_exit if {
	exit_info != null
	date_year(exit_info.date) == year
}

# --- Nichterfüllung von Zugangsvoraussetzungen (SRL 1.12.1.1) -------------------------------

access_violation_ids := {"O61B-ZT-001", "O61B-ATB-001", "O61B-ATB-002", "O61B-ATB-003", "O61B-VZ-003", "O61B-AN-001", "O61B-AN-002", "O61B-TB-001", "O61B-TB-005"}

access_requirements_failed if {
	some v in violations
	v.rule_id in access_violation_ids
}

access_failure_consequence := "no_contract" if {
	access_requirements_failed
	contract_start_year == year
}

access_failure_consequence := "no_premium_this_year" if {
	access_requirements_failed
	contract_start_year != year
}

# --- Kürzungsstufen (ATB 8.2) ------------------------------------------------------------------

sanction_level := object.get(o6_1b_input, "sanction_level", null)

sanction_reduction_percent := s.reduction_percent if {
	sanction_level != null
	some s in general.sanction_levels
	s.level == sanction_level
	sanction_year_applicable(s)
}

sanction_year_applicable(s) if {
	not s.until_year
	not s.from_year
}

sanction_year_applicable(s) if year <= s.until_year

sanction_year_applicable(s) if year >= s.from_year

exclusion_from_measure if object.get(o6_1b_input, "full_reductions_in_contract_period", 0) >= 2

# --- Auszahlung (ATB 9.1; SRL 1.10.7) -----------------------------------------------------------

payment_deadline := sprintf("%d-%s", [year + 1, general.payment.deadline_month_day])

max_advance_payment := premium_total_modulated * general.payment.advance_max_share

# Tierhaltung: RGVE-Schlüssel, Eigenschaft als tierhaltender Betrieb, Bio-Tierhaltung,
# Eigenbedarfstiere und Equiden (Kap. 4, 5.1, 12; ATB 5.7; SRL 1.5.4, 1.5.5, Anhang A).
package oepul.o6_1b

species_groups := object.get(input, ["livestock", "species_groups"], [])

rgve_factor(key) := f.rgve if {
	some f in data.o6_1b.rgve_key.rgve_factors
	f.key == key
}

is_conventional_equid(g) if {
	g.species == "horses"
	object.get(g, "is_conventional", false) == true
}

# Konventionelle Equiden werden für die Einstufung als tierhaltender Betrieb nicht berücksichtigt.
counted_rgve_group(g) if {
	_ := rgve_factor(object.get(g, "rgve_key", ""))
	not is_conventional_equid(g)
	object.get(g, "kept_in_austria", true) == true
}

group_rgve(g) := object.get(g, "animal_count", 0) * rgve_factor(g.rgve_key)

total_rgve := sum([group_rgve(g) | some g in species_groups; counted_rgve_group(g)])

# Futterfläche = Grünland + Ackerfutterflächen (inkl. Flächen in Naturschutz / Bergmähdern)
is_arable_forage(p) if {
	p.land_use == "arable"
	land_use_type(p) in lists.arable_forage
}

is_arable_forage(p) if {
	p.land_use == "arable"
	crop_name(p) in lists.arable_forage
}

forage_area_ha := sum([area(p) | some p in parcels; is_forage_parcel(p)])

is_forage_parcel(p) if is_grassland(p)

is_forage_parcel(p) if {
	not is_grassland(p)
	is_arable_forage(p)
}

rgve_per_ha := share(total_rgve, forage_area_ha)

is_livestock_farm if {
	forage_area_ha > 0
	rgve_per_ha >= data.o6_1b.rgve_key.thresholds.livestock_farm_min_rgve_per_ha
}

livestock_category := "non_livestock" if not is_livestock_farm

livestock_category := "livestock_lt_1_4" if {
	is_livestock_farm
	rgve_per_ha < caps.grassland_base_rgve_threshold
}

livestock_category := "livestock_ge_1_4" if {
	is_livestock_farm
	rgve_per_ha >= caps.grassland_base_rgve_threshold
}

stocking_below_1_4 if rgve_per_ha < caps.kreislauf_max_rgve_per_ha_exclusive

# --- Bio-Tierhaltung (Kap. 5.1; SRL 2.1 B) -------------------------------------------

is_own_use_exception(g) if {
	object.get(g, "own_use", false) == true
	g.species == "pigs"
	object.get(g, "category", "") == "fattening_pig"
}

is_own_use_exception(g) if {
	object.get(g, "own_use", false) == true
	g.species == "poultry"
	object.get(g, "category", "") == "chicken"
}

own_use_count(species) := sum([object.get(g, "animal_count", 0) |
	some g in species_groups
	is_own_use_exception(g)
	g.species == species
])

violations contains {"rule_id": "O61B-BV-003", "message": "Mehr als 2 nicht zertifizierte Mastschweine für den Eigenbedarf"} if {
	own_use_count("pigs") > general.own_use_animals.max_fattening_pigs
}

violations contains {"rule_id": "O61B-BV-003", "message": "Mehr als 10 nicht zertifizierte Hühner für den Eigenbedarf"} if {
	own_use_count("poultry") > general.own_use_animals.max_chickens
}

violations contains {"rule_id": "O61B-BV-003", "message": sprintf("Eigenbedarfsregelung gilt nicht für Tierart/Kategorie %s/%s", [g.species, object.get(g, "category", "")])} if {
	some g in species_groups
	object.get(g, "own_use", false) == true
	not is_own_use_exception(g)
}

violations contains {"rule_id": "O61B-BV-002", "message": sprintf("Nicht biologisch gehaltene Nutztiere (%s) – konventioneller Tierhaltungs-Teilbetrieb unzulässig", [g.species])} if {
	livestock_must_be_organic
	some g in species_groups
	object.get(g, "animal_count", 0) > 0
	object.get(g, "is_certified_organic", true) == false
	not is_own_use_exception(g)
	not is_conventional_equid(g)
}

violations contains {"rule_id": "O61B-BV-004", "message": "Gleichzeitige Haltung konventioneller und biologischer Equiden unzulässig"} if {
	some g1 in species_groups
	is_conventional_equid(g1)
	some g2 in species_groups
	g2.species == "horses"
	object.get(g2, "is_conventional", false) == false
	object.get(g2, "animal_count", 0) > 0
}

violations contains {"rule_id": "O61B-BV-007", "message": "Konventionelle Equiden: Kreuz bei 'Konventionelle Pferdehaltung' in der Beilage MFA-Angaben fehlt"} if {
	some g in species_groups
	is_conventional_equid(g)
	object.get(o6_1b_input, "conventional_horse_declared_in_mfa", false) != true
}

# Tierbestand in Österreich (ATB 5.6; SRL 1.4.2.2)
violations contains {"rule_id": "O61B-ATB-008", "message": "Außerhalb Österreichs gehaltene Tiere sind nicht anrechenbar"} if {
	some g in species_groups
	object.get(g, "kept_in_austria", true) == false
	_ := rgve_factor(object.get(g, "rgve_key", ""))
}

# Allgemeine Förderbedingungen der Maßnahme: PSM-Codierung, Erhaltung des Grünlandausmaßes,
# Anbaudiversifizierung, Weiterbildung, Flächenförderfähigkeit und Mindestbewirtschaftung
# (Kap. 3.2, 5.2-5.5, 10; ATB 4, 5.4-5.6; SRL 1.5.3, 1.6, 2.1 B).
package oepul.o6_1b

# --- 5.2 Angabe von Pflanzenschutzmitteleinsätzen ------------------------------------

psm_coding_required if year <= general.deadlines.psm_coding_last_year

violations contains {"rule_id": "O61B-PSM-001", "message": sprintf("Flächiger PSM-Einsatz auf Schlag %s ohne Code PSMBIO/PSMCS", [p.parcel_id])} if {
	psm_coding_required
	some p in parcels
	object.get(p, ["operations", "psm_used"], false) == true
	count(codes(p) & {c | some c in lists.psm_codes_until_2025}) == 0
}

# --- 5.3 Erhaltung des Grünlandausmaßes -------------------------------------------------

grassland_input := object.get(o6_1b_input, "grassland", {})

grassland_reference_ha := object.get(grassland_input, "reference_area_ha", null)

# Umgewandeltes Grünland abzüglich Grünlandneuanlagen (Neuanlagen füllen die Toleranz wieder auf)
grassland_net_conversion_ha := object.get(grassland_input, "converted_ha", 0) - object.get(grassland_input, "new_grassland_ha", 0)

grassland_reduction_ha := max2(grassland_net_conversion_ha, grassland_reference_ha - grassland_area_ha) if grassland_reference_ha != null

grassland_reduction_ha := grassland_net_conversion_ha if grassland_reference_ha == null

violations contains {"rule_id": "O61B-GL-001", "message": sprintf("Grünlandumbruch von %v ha überschreitet die Toleranz von 1,00 ha", [round2(grassland_reduction_ha)])} if {
	grassland_reduction_ha > general.tolerances.grassland_conversion_tolerance_ha
}

# --- 5.4 Anbaudiversifizierung auf Ackerflächen -----------------------------------------

crop_base_name(p) := object.get(p, ["crop", "mixture_main_component"], crop_name(p))

crop_species(p) := s if {
	s := object.get(p, ["crop", "species"], null)
	s != null
}

crop_species(p) := s if {
	object.get(p, ["crop", "species"], null) == null
	s := lists.crop_species_map[crop_base_name(p)]
}

crop_species(p) := crop_base_name(p) if {
	object.get(p, ["crop", "species"], null) == null
	not lists.crop_species_map[crop_base_name(p)]
}

is_cereal(p) if {
	crop_species(p) in lists.cereals
	object.get(p, ["crop", "cereal_share_percent"], 100) >= 50
}

is_maize(p) if crop_species(p) in lists.maize

diversification_applies if arable_area_ha > general.diversification.arable_threshold_ha_exclusive

cereal_maize_area_ha := sum([area(p) | some p in parcels; is_arable(p); cereal_or_maize(p)])

cereal_or_maize(p) if is_cereal(p)

cereal_or_maize(p) if {
	not is_cereal(p)
	is_maize(p)
}

cereal_maize_share := share(cereal_maize_area_ha, arable_area_ha)

exempt_from_55(p) if land_use_type(p) in lists.arable_forage

exempt_from_55(p) if crop_species(p) in lists.arable_forage

exempt_from_55(p) if {
	year >= 2025
	land_use_type(p) in lists.diversification_55_exempt_from_2025
}

exempt_from_55(p) if {
	year >= 2025
	crop_species(p) in lists.diversification_55_exempt_from_2025
}

crop_shares[s] := share(a, arable_area_ha) if {
	some p in parcels
	is_arable(p)
	not exempt_from_55(p)
	s := crop_species(p)
	a := sum([area(q) | some q in parcels; is_arable(q); not exempt_from_55(q); crop_species(q) == s])
}

violations contains {"rule_id": "O61B-AD-001", "message": sprintf("Getreide- und Maisanteil %v %% über 75 %%", [round2(cereal_maize_share * 100)])} if {
	diversification_applies
	cereal_maize_share > general.diversification.max_cereal_maize_share
}

violations contains {"rule_id": "O61B-AD-002", "message": sprintf("Kultur %s hat einen Anteil von %v %% an der Ackerfläche (max. 55 %%)", [s, round2(v * 100)])} if {
	diversification_applies
	some s, v in crop_shares
	v > general.diversification.max_single_crop_share
}

# --- 5.5 Weiterbildung ------------------------------------------------------------------

training_courses := object.get(o6_1b_input, ["training", "courses"], [])

creditable_course(c) if {
	c.date >= general.training.creditable_from
	c.date <= general.training.deadline
	object.get(c, "provider_recognized", false) == true
	object.get(c, "credited_elsewhere", false) == false
	object.get(c, "attendee_left_before_deadline", false) == false
}

training_hours(topic) := sum([c.hours | some c in training_courses; c.topic == topic; creditable_course(c)])

training_deadline_passed if year > date_year(general.training.deadline)

violations contains {"rule_id": "O61B-WB-001", "message": "Weiterbildung zu biodiversitätsrelevanten Themen (mind. 3 Stunden) nicht fristgerecht bis 31.12.2025 absolviert"} if {
	training_deadline_passed
	training_hours("biodiversity") < general.training.biodiversity_min_hours
}

violations contains {"rule_id": "O61B-WB-002", "message": "Weiterbildung zur biologischen Wirtschaftsweise (mind. 5 Stunden) nicht fristgerecht bis 31.12.2025 absolviert"} if {
	training_deadline_passed
	training_hours("organic") < general.training.organic_min_hours
}

# --- 3.2 / ATB 5.5 Förderfähigkeit von Flächen -----------------------------------------

violations contains {"rule_id": "O61B-FL-006", "message": sprintf("Obstanlage %s ohne veredeltes Pflanzgut muss mit Code OP beantragt werden", [p.parcel_id])} if {
	some p in parcels
	is_special_crop(p)
	is_fruit(p)
	object.get(p, ["crop", "is_grafted"], true) == false
	not opted_out(p)
}

is_fruit(p) if {
	some o in lists.obst
	o.crop == crop_name(p)
	o.from_year <= year
}

in_national_park_without_premium(p) if object.get(p, "national_park", "") in general.national_parks_no_area_premium

located_outside_austria(p) if object.get(p, "in_austria", true) == false

# Mindestbewirtschaftung: Ernte auf zumindest 85 % des Schlages (ATB 5.4; SRL 1.6.3.1)
harvest_required(p) if {
	is_arable(p)
	not is_arable_forage(p)
	not is_arable_div(p)
	not opted_out(p)
	land_use_type(p) != "Grünbrache"
}

violations contains {"rule_id": "O61B-ATB-004", "message": sprintf("Ernteverpflichtung (85 %%) auf Schlag %s nicht erfüllt", [p.parcel_id])} if {
	some p in parcels
	harvest_required(p)
	object.get(p, ["operations", "harvested_share_percent"], 100) < 85
	not drought_harvest_waiver(p)
}

violations contains {"rule_id": "O61B-ATB-004", "message": sprintf("Grünland-/Ackerfutterfläche %s ohne jährliche vollflächige Mahd mit Verbringung oder Beweidung", [p.parcel_id])} if {
	some p in parcels
	is_forage_parcel(p)
	not is_bergmaehder(p)
	not is_arable_div(p)
	not is_grassland_div(p)
	object.get(p, ["operations", "annual_full_use_done"], true) == false
}

# Betriebliche Optionen und flächenbezogene Zuschläge: Landschaftselemente, Streuobst,
# Mehrnutzenhecken, Bio-Bienenhaltung, Naturschutz-Monitoring, Transaktionskosten,
# seltene Kulturpflanzen, Wildkräuter- und Brutflächen, Pheromonfallen (Kap. 7, 8.5, 8.8, 8.9, 10).
package oepul.o6_1b

# --- 7.1 / 7.2 Punktförmige Landschaftselemente und Streuobstbäume ----------------------

lse_cfg := general.lse

point_elements := object.get(input, ["land", "point_landscape_elements"], [])

lse_eligible(e) if {
	object.get(e, "distance_to_farmland_m", 0) <= lse_cfg.max_distance_to_farmland_m
	object.get(e, "crown_diameter_m", 0) >= lse_cfg.min_crown_diameter_m
	object.get(e, "area_m2", 0) <= lse_cfg.max_area_m2
	object.get(e, "min_distance_to_other_element_m", 0) >= lse_cfg.min_spacing_m
	object.get(e, "in_control", true) == true
	object.get(e, "on_alm_or_hutweide", false) == false
	object.get(e, "is_gloez_element", false) == false
	object.get(e, "retained_full_year", true) == true
	object.get(e, "applied_as", "LSE Bäume/Büsche") == "LSE Bäume/Büsche"
}

streuobst_species_allowed(sp) if {
	some s in lists.streuobst_species
	s.species == sp
	s.from_year <= year
}

streuobst_eligible(e) if {
	lse_eligible(e)
	"SO" in object.get(e, "oepul_codes", [])
	streuobst_species_allowed(object.get(e, "fruit_species", ""))
	object.get(e, "stem_form", "") in lists.streuobst_stem_forms
	object.get(e, "has_permanent_support_frame", false) == false
	streuobst_form_ok(e)
}

streuobst_form_ok(e) if object.get(e, "is_wild_form", false) == false

streuobst_form_ok(e) if {
	object.get(e, "is_wild_form", false) == true
	e.fruit_species in lists.streuobst_wild_forms_allowed
}

lse_kind(e) := "streuobst" if streuobst_eligible(e)

lse_kind(e) := "other" if {
	lse_eligible(e)
	not streuobst_eligible(e)
}

field_piece_area(fp_id) := fp.area_ha if {
	some fp in field_pieces
	fp.field_piece_id == fp_id
}

lse_cap(fp_id) := floor(caps.lse_max_per_ha_field_piece * field_piece_area(fp_id))

lse_count(fp_id, kind) := count([e | some e in point_elements; object.get(e, "field_piece_id", "") == fp_id; lse_kind(e) == kind])

lse_field_piece_ids := {object.get(e, "field_piece_id", "") | some e in point_elements}

# Streuobstbäume werden bei Überschreitung der 80 Elemente/ha vorrangig berücksichtigt (Annahme A-07)
lse_paid_streuobst(fp_id) := min2(lse_count(fp_id, "streuobst"), lse_cap(fp_id))

lse_paid_other(fp_id) := min2(lse_count(fp_id, "other"), clamp0(lse_cap(fp_id) - lse_paid_streuobst(fp_id)))

lse_paid(fp_id, "streuobst") := lse_paid_streuobst(fp_id)

lse_paid(fp_id, "other") := lse_paid_other(fp_id)

lse_paid_total(kind) := sum([lse_paid(fp, kind) | some fp in lse_field_piece_ids])

violations contains {"rule_id": "O61B-LE-001", "message": sprintf("Punktförmiges Landschaftselement %s erfüllt die Definition nicht", [e.element_id])} if {
	some e in point_elements
	not lse_eligible(e)
	object.get(e, "is_gloez_element", false) == false
}

violations contains {"rule_id": "O61B-SO-001", "message": sprintf("Streuobstbaum %s (Code SO) erfüllt die Förderkriterien nicht", [e.element_id])} if {
	some e in point_elements
	"SO" in object.get(e, "oepul_codes", [])
	not streuobst_eligible(e)
}

# --- 7.3 Mehrnutzenhecken ----------------------------------------------------------------------

hedge_cfg := general.hedge

hedge_eligible(h) if {
	h.planted_date >= hedge_cfg.planted_from
	h.planted_date <= sprintf("%d-%s", [year, hedge_cfg.planted_until_month_day])
	object.get(h, "avg_width_m", 0) >= hedge_cfg.min_avg_width_m
	object.get(h, "avg_width_m", 0) <= hedge_cfg.max_avg_width_m
	object.get(h, "herbaceous_share_percent", 0) >= hedge_cfg.min_herbaceous_share_percent
	object.get(h, "adjoins_own_arable_field_piece", false) == true
	object.get(h, "long_side_adjoins_forest_or_flat_lse", false) == false
	object.get(h, "state_concept", false) == true
	object.get(h, "confirmed_by_state_in_gis", false) == true
	object.get(h, "fertilizer_or_psm_used", false) == false
	object.get(h, "herbaceous_area_used", false) == false
	object.get(h, "mostly_shrubs_and_fruit_trees", true) == true
}

violations contains {"rule_id": "O61B-MH-002", "message": sprintf("Mehrnutzenhecke %s erfüllt die Förderverpflichtungen nicht", [h.hedge_id])} if {
	some h in hedges
	not hedge_eligible(h)
}

hedge_area_paid_ha := sum([h.area_ha | some h in hedges; hedge_eligible(h)])

# --- 7.4 Bio-Bienenhaltung ----------------------------------------------------------------------

beekeeping := object.get(o6_1b_input, "beekeeping", {})

bee_hives_eligible := min2(object.get(beekeeping, "economic_colony_hives", 0), caps.bee_hives_max_per_farm) if {
	object.get(beekeeping, "organic_control", false) == true
	object.get(beekeeping, "declared_in_mfa", false) == true
	object.get(beekeeping, "sector_programme_organic_feed_or_wax_compensated", false) == false
}

bee_hives_eligible := 0 if not bee_premium_conditions

bee_premium_conditions if {
	object.get(beekeeping, "organic_control", false) == true
	object.get(beekeeping, "declared_in_mfa", false) == true
	object.get(beekeeping, "sector_programme_organic_feed_or_wax_compensated", false) == false
}

# --- 7.5 Naturschutz-Monitoring -------------------------------------------------------------------

monitoring := object.get(o6_1b_input, "monitoring", [])

farm_nat_auflagen := {a | some p in parcels; some a in nat_auflagen(p)} | {a | some a in object.get(o6_1b_input, "nat_auflagen_farm", [])}

monitoring_programme(id) := m if {
	some m in lists.monitoring_programmes
	m.id == id
}

monitoring_combination_ok(prog) if prog.requires_measure == null

monitoring_combination_ok(prog) if {
	prog.requires_measure != null
	prog.requires_measure in participating_measures
	count(farm_nat_auflagen & {a | some a in prog.requires_any_auflage}) > 0
}

monitoring_eligible(m) if {
	prog := monitoring_programme(m.programme)
	monitoring_combination_ok(prog)
	object.get(m, "participation_confirmation", false) == true
	object.get(m, "data_complete", false) == true
	object.get(m, "applied_in_measure_application", false) == true
	intro_ok(m)
}

intro_ok(m) if object.get(m, "first_year", false) == false

intro_ok(m) if {
	object.get(m, "first_year", false) == true
	object.get(m, "intro_event_completed", false) == true
}

violations contains {"rule_id": "O61B-MO-002", "message": sprintf("Monitoringprogramm %s ohne erforderliche Kombination mit Naturschutz-Auflage", [m.programme])} if {
	some m in monitoring
	prog := monitoring_programme(m.programme)
	not monitoring_combination_ok(prog)
}

violations contains {"rule_id": "O61B-MO-001", "message": sprintf("Monitoringprogramm %s: Teilnahmebestätigung, Einführungsveranstaltung oder Datenerfassung fehlt", [m.programme])} if {
	some m in monitoring
	prog := monitoring_programme(m.programme)
	monitoring_combination_ok(prog)
	not monitoring_eligible(m)
}

violations contains {"rule_id": "O61B-VZ-004", "message": "Einstieg in Naturschutz-Monitoring nach dem Förderjahr 2028 nicht möglich"} if {
	some m in monitoring
	object.get(m, "first_year", false) == true
	year > general.deadlines.monitoring_last_entry_year
}

# --- 8.5 Seltene, regional wertvolle landwirtschaftliche Kulturpflanzen (SLK) --------------------

variety_row(name) := v if {
	some v in data.o6_1b.rare_varieties.varieties
	v.variety == name
	v.valid_from_year <= year
}

slk_variety_pure(p) if object.get(p, ["crop", "is_variety_pure"], false) == true

slk_variety_pure(p) if object.get(p, ["crop", "poppy_strip_cultivation"], false) == true

slk_first_use_year(p) if object.get(p, ["crop", "multi_year"], false) == false

slk_first_use_year(p) if {
	object.get(p, ["crop", "multi_year"], false) == true
	object.get(p, ["crop", "first_year_of_use"], false) == true
}

slk_eligible(p) if {
	is_arable(p)
	has_code(p, "SLK")
	_ := variety_row(object.get(p, ["crop", "variety"], ""))
	slk_variety_pure(p)
	slk_first_use_year(p)
	object.get(p, ["crop", "seed_documented"], false) == true
}

violations contains {"rule_id": "O61B-ZA-004", "message": sprintf("SLK-Schlag %s: Sorte nicht in der Sortenliste, nicht sortenrein, nicht dokumentiert oder nicht im ersten Nutzungsjahr", [p.parcel_id])} if {
	some p in parcels
	has_code(p, "SLK")
	not slk_eligible(p)
}

# --- 8.8 Wildkräuter- und Brutflächen (WB) -------------------------------------------------------

wb_cfg := general.wildkraeuter

wb_ban_end(p) := d if {
	th := [e.date | some e in use_events(p); e.type == "thresh"; date_year(e.date) == year]
	count(th) > 0
	d := min2(min(th), sprintf("%d-%s", [year, wb_cfg.ban_end]))
}

wb_ban_end(p) := sprintf("%d-%s", [year, wb_cfg.ban_end]) if {
	count([e | some e in use_events(p); e.type == "thresh"; date_year(e.date) == year]) == 0
}

wb_in_ban(p, d) if {
	d >= sprintf("%d-%s", [year, wb_cfg.ban_start])
	d < wb_ban_end(p)
}

wb_forbidden_activity(p) if {
	some f in fertilizer_applications(p)
	wb_in_ban(p, f.date)
}

wb_forbidden_activity(p) if {
	some v in object.get(p, ["operations", "driving_events"], [])
	object.get(v, "crossing_only", false) == false
	wb_in_ban(p, v.date)
}

wb_forbidden_activity(p) if {
	some d in object.get(p, ["operations", "psm_application_dates"], [])
	wb_in_ban(p, d)
}

wb_forbidden_activity(p) if {
	some d in object.get(p, ["operations", "mechanical_weeding_dates"], [])
	wb_in_ban(p, d)
}

# Bis 30.6. ist als Ernte nur der Drusch erlaubt
wb_forbidden_activity(p) if {
	some e in use_events(p)
	e.type in {"harvest", "mow", "chop", "graze"}
	date_year(e.date) == year
	md(e.date) <= wb_cfg.ban_end
}

wb_sowing_ok(p) if object.get(p, ["crop", "summer_cereal"], false) == false

wb_sowing_ok(p) if {
	object.get(p, ["crop", "summer_cereal"], false) == true
	md(object.get(p, ["operations", "sowing_date"], "0000-12-31")) < wb_cfg.summer_cereal_sow_before
}

wb_eligible(p) if {
	is_arable(p)
	has_code(p, "WB")
	is_cereal(p)
	object.get(p, ["operations", "row_spacing_cm"], 0) >= wb_cfg.min_row_spacing_cm
	object.get(p, ["operations", "undersown"], false) == false
	wb_sowing_ok(p)
	not wb_forbidden_activity(p)
}

violations contains {"rule_id": "O61B-ZA-012", "message": sprintf("Wildkräuter- und Brutfläche %s erfüllt die Förderbedingungen nicht", [p.parcel_id])} if {
	some p in parcels
	has_code(p, "WB")
	not wb_eligible(p)
}

# --- 8.9 Pheromonfallen bei Zuckerrüben (PZR) -----------------------------------------------------

pzr_cfg := general.pheromone

pzr_land_use_ok(p) if land_use_type(p) in lists.pheromone_land_use_types

pzr_land_use_ok(p) if object.get(p, ["operations", "sugar_beet_previous_year"], false) == true

traps(p) := object.get(p, ["operations", "pheromone_traps"], {})

pzr_eligible(p) if {
	year >= 2025
	is_arable(p)
	has_code(p, "PZR")
	pzr_land_use_ok(p)
	t := traps(p)
	object.get(t, "traps_per_ha", 0) >= pzr_cfg.min_traps_per_ha
	object.get(t, "installed_within_days_after_sowing", 999) <= pzr_cfg.install_within_days_after_sowing
	object.get(t, "days_in_field", 0) >= pzr_cfg.min_days_in_field
	object.get(t, "emptying_count", 0) >= pzr_cfg.min_emptyings
	object.get(t, "removed_before_harvest", false) == true
	object.get(t, "records_complete", false) == true
	object.get(t, "pheromone_receipts_kept", false) == true
}

violations contains {"rule_id": "O61B-ZA-013", "message": sprintf("Pheromonfallen-Schlag %s (Code PZR) erfüllt die Förderbedingungen nicht", [p.parcel_id])} if {
	some p in parcels
	has_code(p, "PZR")
	not pzr_eligible(p)
}

# Teilnahmevoraussetzungen: Vertragszeitraum, Einstieg, Bio-Zertifizierung,
# förderwerbende Person, Betriebsmindestgröße, Teilbetrieb und Maßnahmenkombination.
package oepul.o6_1b

# --- Vertragszeitraum (Kap. 3.1; ATB 5.9; SRL 1.7.1.2) -----------------------------

contract_start_year := object.get(o6_1b_input, "contract_start_year", null)

contract_period_row := row if {
	some row in general.contract_periods
	date_year(row.start) == contract_start_year
}

contract_period_years := contract_period_row.years

contract_end_date := contract_period_row.end

# Antragsjahr liegt innerhalb des Vertragszeitraums
within_contract_period if {
	contract_start_year != null
	year >= contract_start_year
	year <= date_year(general.deadlines.contract_end)
}

# Optionale Zuschläge: Vertragszeitraum ein Kalenderjahr (Kap. 3.1)
optional_supplement_contract_period := {"start": sprintf("%d-01-01", [year]), "end": sprintf("%d-12-31", [year])}

violations contains {"rule_id": "O61B-VZ-003", "message": "Vertragsbeginn nach dem letztmöglichen Einstiegsjahr 2025"} if {
	contract_start_year != null
	contract_start_year > general.deadlines.last_entry_contract_year
}

violations contains {"rule_id": "O61B-VZ-003", "message": "Maßnahmenantrag nicht bis 31.12. vor Vertragsbeginn gestellt"} if {
	contract_start_year != null
	app := object.get(o6_1b_input, "application_date", null)
	app != null
	app > sprintf("%d-12-31", [contract_start_year - 1])
}

# --- Bio-Zertifizierung (Kap. 3.4; SRL 2.1 B Förderverpflichtungen) -----------------

organic := object.get(input, ["farm", "certifications", "organic"], {})

violations contains {"rule_id": "O61B-ZT-001", "message": "Betrieb nicht als biologisch wirtschaftender Betrieb bei der Lebensmittelbehörde registriert"} if {
	object.get(organic, "registered_with_food_authority", false) != true
}

violations contains {"rule_id": "O61B-ZT-001", "message": "Kein Vertrag mit einer anerkannten Bio-Kontrollstelle spätestens ab 1. Jänner des ersten Vertragsjahres"} if {
	contract_start_year != null
	start := object.get(organic, "control_contract_start_date", null)
	not control_contract_started_in_time(start)
}

control_contract_started_in_time(start) if {
	start != null
	start <= sprintf("%d-01-01", [contract_start_year])
}

violations contains {"rule_id": "O61B-ZT-001", "message": "Kontrollvertrag endet vor dem Ende des Vertragszeitraumes"} if {
	end := object.get(organic, "control_contract_end_date", null)
	end != null
	end < general.deadlines.contract_end
}

violations contains {"rule_id": "O61B-ZT-002", "message": "Wechsel der Bio-Kontrollstelle mit zeitlicher Unterbrechung"} if {
	object.get(organic, "control_body_change_without_gap", true) == false
}

# --- Förderwerbende Person (ATB 5.2; SRL 1.4) ---------------------------------------

applicant := object.get(input, ["oepul", "applicant"], {})

violations contains {"rule_id": "O61B-ATB-001", "message": "Personentyp kommt als förderwerbende Person nicht in Betracht"} if {
	pt := object.get(applicant, "person_type", null)
	pt != null
	not pt in lists.applicant_types_eligible
}

violations contains {"rule_id": "O61B-ATB-001", "message": "Beteiligung von Gebietskörperschaften übersteigt 25 %"} if {
	object.get(applicant, "public_body_share_percent", 0) > lists.parameters.public_body_max_share_percent
}

violations contains {"rule_id": "O61B-ATB-002", "message": "Kein aktiver Landwirt bzw. keine Bewirtschaftung im eigenen Namen und auf eigene Rechnung"} if {
	some flag in ["is_active_farmer", "farms_in_own_name", "has_control_over_areas"]
	object.get(applicant, flag, true) == false
}

# --- Betriebsmindestgröße im 1. ÖPUL-Teilnahmejahr (ATB 5.3; SRL 1.6.1) --------------

first_oepul_year := object.get(input, ["oepul", "first_participation_year"], null)

protected_cultivation_ha := sum([area(p) | some p in parcels; land_use_type(p) == "GA"])

minimum_size_area_ha := sum([area(p) | some p in parcels; p.land_use in {"arable", "grassland", "special_crop", "alpine_pasture"}])

meets_minimum_farm_size if protected_cultivation_ha >= general.min_farm_size_first_year.protected_cultivation_ha

meets_minimum_farm_size if minimum_size_area_ha >= general.min_farm_size_first_year.agricultural_area_ha

violations contains {"rule_id": "O61B-ATB-003", "message": "Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr nicht erreicht"} if {
	first_oepul_year == year
	not meets_minimum_farm_size
}

# --- Biologischer Teilbetrieb (Kap. 3.3; SRL 2.1 B Option Teilbetrieb) ----------------

partial_farm := object.get(o6_1b_input, "partial_farm", {})

is_partial_farm if object.get(partial_farm, "is_partial", false) == true

partial_organic_area := object.get(partial_farm, "organic_culture_area", null)

violations contains {"rule_id": "O61B-TB-001", "message": "Teilbetrieb ohne eigenständige Betriebsanlagen und Nutzflächen bzw. ohne getrennte Lagerung der Betriebsmittel"} if {
	is_partial_farm
	some flag in ["separate_facilities_and_land", "separate_input_storage"]
	object.get(partial_farm, flag, false) != true
}

violations contains {"rule_id": "O61B-TB-002", "message": "Teilbetrieb: biologischer Kulturbereich muss 'arable_grassland' oder 'wine_fruit_hops' sein"} if {
	is_partial_farm
	not partial_organic_area in {"arable_grassland", "wine_fruit_hops"}
}

violations contains {"rule_id": "O61B-TB-005", "message": "Option Teilbetrieb nicht im Maßnahmenantrag beantragt"} if {
	is_partial_farm
	object.get(partial_farm, "applied_in_measure_application", false) != true
}

# Alle biologisch bewirtschafteten Schläge des Teilbetriebs sind mit BIO zu codieren (Kap. 10, 3.2)
organic_culture_land_uses := lists.culture_areas[partial_organic_area]

violations contains {"rule_id": "O61B-FL-004", "message": sprintf("Schlag %s des biologischen Kulturbereichs ohne Code BIO", [p.parcel_id])} if {
	is_partial_farm
	some p in parcels
	p.land_use in organic_culture_land_uses
	not excluded_land_use(p)
	not has_code(p, "BIO")
}

# Tierhaltung ist an den Kulturbereich Grünland/Ackerland gebunden (Kap. 3.3)
livestock_must_be_organic if not is_partial_farm

livestock_must_be_organic if {
	is_partial_farm
	partial_organic_area == "arable_grassland"
}

# --- Maßnahmenkombination (Kap. 10; SRL 1.9.4 und 2.1 B Höhe der Förderung) ----------

violations contains {"rule_id": "O61B-AN-001", "message": sprintf("Betriebliche Kombination mit %s ausgeschlossen", [m.label])} if {
	some m in lists.excluded_combination_measures
	m.partial_farm_exception == "mutual_culture_area"
	m.measure in participating_measures
	not is_partial_farm
}

violations contains {"rule_id": "O61B-AN-002", "message": "Teilnahme an 'Nichtproduktive Ackerflächen' nur bei Bio-Teilbetrieb mit Kulturbereich Wein, Obst und Hopfen möglich"} if {
	"o6_1c_nonproductive" in participating_measures
	not partial_farm_wine_fruit_hops
}

partial_farm_wine_fruit_hops if {
	is_partial_farm
	partial_organic_area == "wine_fruit_hops"
}

# --- Maßnahmenwechsel in die Biologische Wirtschaftsweise (ATB 6.2; SRL 1.7.3.2) -----

measure_switch := object.get(o6_1b_input, "switched_from", null)

measure_switch_without_repayment if {
	measure_switch in general.measure_switch_into_o6_1b_from
	object.get(o6_1b_input, "switch_date", "9999-12-31") <= general.deadlines.measure_switch_latest
}

